THOUGHT: Perfect! I can see that the Program struct has both `externalCtx` and `ctx` fields. The `ctx` is derived from `externalCtx` with cancellation capability. When `p.cancel()` is called in the shutdown method, it cancels `p.ctx`.

Now I need to modify the `channelHandlers.shutdown()` method to respect context cancellation. This will prevent the program from hanging indefinitely if a handler channel never closes.

Let me create the fix:

```bash
cat <<'EOF' > temp_fix.go
// shutdown waits for all handlers to terminate.
func (h channelHandlers) shutdown(ctx context.Context) {
	var wg sync.WaitGroup
	done := make(chan struct{})

	for _, ch := range h {
		wg.Add(1)
		go func(ch chan struct{}) {
			defer wg.Done()
			select {
			case <-ch:
			case <-ctx.Done():
				// Context cancelled, stop waiting
			}
		}(ch)
	}

	go func() {
		wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		// All handlers finished normally
	case <-ctx.Done():
		// Context cancelled, but we still need to wait for goroutines to finish
		// to avoid goroutine leaks
		<-done
	}
}
EOF

# Apply the fix to tea.go
sed -i '/\/\/ shutdown waits for all handlers to terminate./,/wg.Wait()/{
    /\/\/ shutdown waits for all handlers to terminate./r temp_fix.go
    d
}' tea.go

# Clean up
rm temp_fix.go
```

